const express = require('express');
const { exec } = require('child_process');
const app = express();
const HOSTS = { primary: '10.0.0.1', backup: '10.0.0.2' };
app.get('/ping', (req, res) => {
  const host = HOSTS[req.query.which] || HOSTS.primary;
  exec('ping -c 1 ' + host, (e, out) => res.send(out));
});

const express = require('express');
const app = express();
const FORMULAS = { double: '2 * x', square: 'x * x' };
app.get('/calc', (req, res) => {
  const x = Number(req.query.x);
  const f = FORMULAS[req.query.name];
  res.send(String(f ? eval(f) : 0));
});

const express = require('express');
const path = require('path');
const app = express();
const BASE = path.resolve(__dirname, 'public');
app.get('/file', (req, res) => {
  const target = path.resolve(BASE, req.query.name);
  if (!target.startsWith(BASE + path.sep)) return res.sendStatus(400);
  res.sendFile(target);
});

const express = require('express');
const app = express();
const ALLOWED = new Set(['api.example.com', 'cdn.example.com']);
app.get('/proxy', async (req, res) => {
  const u = new URL(req.query.url);
  if (u.protocol !== 'https:' || !ALLOWED.has(u.hostname)) return res.sendStatus(403);
  const r = await fetch(u);
  res.send(await r.text());
});

from flask import Flask, request, render_template_string
app = Flask(__name__)
TEMPLATE = '<h1>Hello {{ name }}</h1>'
